/// Parses a BEGIN statement.
fn parse_begin(&mut self) -> Result<ast::Statement> {
    let read_only = self.next_if_keyword() == Some(Keyword::Read);
    if read_only {
        self.expect(Token::Keyword(Keyword::Write))?;
    }
    self.expect(Token::Keyword(Keyword::Transaction))?;
    let as_of = if self.next_if_keyword() == Some(Keyword::As) {
        self.expect(Token::Keyword(Keyword::Of))?;
        let expr = self.parse_expression()?;
        // Extract the version number from the expression
        match &expr {
            ast::Expression::Literal(ast::Literal::Integer(v)) => Some(*v),
            _ => return errinput!("AS OF version must be an integer"),
        }
    } else {
        None
    };
    Ok(ast::Statement::Begin { read_only, as_of })
}
